  | "runtime.ready"
  | "runtime.pong"
  | "runtime.status"
  | "turn.started"
  | "turn.interrupt.accepted"
  | "turn.interrupt.rejected"
  | "response.delta"
  | "tool.started"
  | "tool.completed"
  | "computer.action.requested"
  | "response.completed"
  | "turn.cancelled"
  | "turn.failed"
  | "task.presence.updated"
  | "task.listed"
  | "task.cancel.accepted"
  | "runtime.error"
  | "trail.appended"
  | "trail.skipped"
  | "product.action.completed"
  | "auth.status"
  | "auth.prompt"
  | "auth.info"
