export function attachTaskExecutionContract(
  command: TurnStartCommand,
  contract: TaskExecutionContract,
): TurnStartCommand {
  Object.defineProperty(command, TASK_EXECUTION_CONTRACT, {
    value: contract,
    enumerable: false,
    configurable: false,
    writable: false,
